INSERT OR REPLACE INTO _fodynest_schema_tmp VALUES ('e2b883b0-d2a6-5ba7-8014-39d500994c11', '');
UPDATE _fodynest_schema_tmp SET s = s || '{"locale":"it","nx_ui_lang":"it","nx_choice_cards":true,"goNextPageAutomatic":true,"allowCompleteSurveyAutomatic":false,"textUpdateMode":"onTyping","showProgressBar":"off","showQuestionNumbers":"off","questionsOnPageMode":"standard","requiredText":"*","pagePrevText":"Indietro","pageNextText":"Avanti","completeText":"Invia le risposte","nx_paradata":true,"nx_no_client_meta":true,"nx_coarse_device":true,"nx_no_probe":["n2_2","n2_3","n2_4","n2_5"],"pages":[{"name":"intro","elements":[{"type":"html","name":"intro_testo","html":"<p style=\"margin:0 0 12px;line-height:1.55\">Questo questionario fa parte di uno studio su FODYNEST.</p><p style=\"margin:0 0 12px;line-height:1.55\">Lo studio confronta <strong style=\"color:#286181\">che cosa chi ha fatto il gioco vuole trasmettere</strong> con che cosa arriva davvero a chi ci gioca.</p><p style=\"margin:0 0 12px;line-height:1.55\">Non ci sono risposte giuste: ci interessa che cosa pensi tu. Meglio frasi concrete che formule generali.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Rispondi senza consultarti con le altre persone di FODY e le designer.</strong> Anche le differenze tra le vostre risposte sono un dato.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ci vogliono circa 25-30 minuti. Puoi interrompere e riprendere dallo stesso dispositivo entro 14 giorni.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Le tue risposte non sono anonime.</strong> Le leggono solo Vittorio Guerrieri e Raluca Fulgu, per NexLudica APS. Le designer non le vedono.</p><p style=\"margin:0 0 12px;line-height:1.55\">Su OSF depositiamo il testo integrale delle tue risposte, con un codice al posto del nome, <strong style=\"color:#286181\">solo se lo autorizzi qui sotto</strong>.</p><p style=\"margin:0 0 12px;line-height:1.55\">Partecipare è libero: puoi ritirarti quando vuoi, senza conseguenze sui tuoi rapporti con NexLudica o con FODY.</p><details style=\"margin:6px 0 16px;border:1px solid #cfd8dc;border-radius:10px\"><summary style=\"cursor:pointer;padding:12px 14px;font-weight:600;color:#286181\">Dettagli su come trattiamo i dati</summary><div style=\"padding:2px 14px 6px;font-size:0.95em\"><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Titolare</strong>: NexLudica APS, Vico Barnabiti 10, 16122 Genova, info@nexludica.org. Responsabile scientifico: Vittorio Guerrieri.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Finalità</strong>: lo studio descritto sopra. I risultati andranno in un articolo scientifico e in un rapporto per le designer e per FODY.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Dati</strong>: il tuo nome e il tuo ruolo in FODY, le tue risposte, data e ora di invio, il tempo passato su ogni pagina e il tipo di dispositivo. Non salviamo l&#x27;indirizzo IP né dati del browser.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Base giuridica</strong>: il tuo consenso (art. 6.1.a GDPR), che puoi revocare in ogni momento.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Chi li tratta</strong>: Vittorio Guerrieri e Raluca Fulgu, autorizzati da NexLudica. Il questionario funziona su Cloudflare, Inc. (USA), che tratta i dati per conto di NexLudica: il database si trova in una regione europea, e gli eventuali trasferimenti verso gli USA si basano sul Data Privacy Framework UE-USA e sulle clausole contrattuali standard.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Pubblicazione su OSF</strong>: se lo autorizzi, prima delle partite depositiamo su OSF (archivio a Francoforte) il testo integrale delle tue risposte, con un codice al posto del nome; la corrispondenza tra codici e nomi la conosciamo solo noi. Prima del deposito ti facciamo rileggere il testo. Chi conosce il gioco sa chi l&#x27;ha fatto: il codice non rende le risposte del tutto anonime. La registrazione diventa pubblica al più tardi dopo 4 anni, e ciò che è pubblicato non si può più ritirare. Se non lo autorizzi, depositiamo solo l&#x27;elenco dei messaggi ricavati dalle tue risposte, con il codice, e un&#x27;impronta digitale del file che prova che le risposte non sono state cambiate.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Conservazione</strong>: le risposte restano sulla piattaforma fino alla fine dell&#x27;analisi e comunque non oltre il 31 dicembre 2027. Poi le conserviamo in un archivio protetto di NexLudica per 5 anni dalla pubblicazione dell&#x27;articolo.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Rischi</strong>: i risultati potrebbero mostrare che il gioco trasmette meno di quanto speravi. Prima della pubblicazione li riceverai e potrai commentarli; il tuo commento sarà riportato.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Diritti</strong>: accesso, rettifica, cancellazione, limitazione, opposizione, portabilità e revoca del consenso, scrivendo a info@nexludica.org. Se revochi prima del deposito su OSF cancelliamo tutto; dopo, cancelliamo tutto ciò che non è già pubblicato. Puoi proporre reclamo al Garante per la protezione dei dati personali (garanteprivacy.it).</p></div></details>"},{"type":"boolean","name":"consent_partecipazione","renderAs":"checkbox","titleLocation":"hidden","title":"Ho letto queste informazioni e accetto di partecipare allo studio.","label":"Ho letto queste informazioni e accetto di partecipare allo studio.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."},{"type":"boolean","name":"consent_dati","renderAs":"checkbox","titleLocation":"hidden","title":"Acconsento al trattamento dei miei dati personali come descritto.","label":"Acconsento al trattamento dei miei dati personali come descritto.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."},{"type":"boolean","name":"osf_integrale","renderAs":"checkbox","titleLocation":"hidden","title":"Deposito integrale su OSF","label":"Facoltativo: autorizzo il deposito su OSF del testo integrale delle mie risposte, con un codice al posto del nome, dopo averlo riletto."}],"title":"Prima di iniziare"},{"name":"p_chi","elements":[{"type":"text","name":"chi_compila","title":"Il tuo nome e il tuo ruolo in FODY","isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti.","autocomplete":"off"}],"title":"Chi compila"},{"name":"p_n1","elements":[{"type":"comment","name":"n1","title":"Immagina una persona che ha appena finito una partita a FODYNEST. Se dovesse dire in una frase che cosa le ha lasciato il gioco, quale frase vorresti sentire?","rows":5,"autoGrow":true,"allowResize":false}],"title":"Che cosa vuoi trasmettere"},{"name":"p_n2","elements":[{"type":"panel","name":"n2_panel","title":"Elenca fino a cinque cose (idee, conoscenze, atteggiamenti) che vorresti arrivassero a chi gioca, in ordine di importanza.","description":"Una per casella: appena ne scrivi una, compare la casella per la successiva.","elements":[{"type":"comment","name":"n2_1","title":"Prima cosa","rows":2,"autoGrow":true,"allowResize":false},{"type":"comment","name":"n2_2","title":"Seconda cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_1} notempty"},{"type":"comment","name":"n2_3","title":"Terza cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_2} notempty"},{"type":"comment","name":"n2_4","title":"Quarta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_3} notempty"},{"type":"comment","name":"n2_5","title":"Quinta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_4} notempty"}]}]},{"name":"p_n3","elements":[{"type":"comment","name":"n3","title":"Che idea di impresa sociale nel tessile, e che idea di FODY, vorresti che si facesse chi gioca?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n4","elements":[{"type":"comment","name":"n4","title":"Che rapporto tra guadagnare e fare scelte etiche vorresti che chi gioca percepisse?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n5","elements":[{"type":"comment","name":"n5","title":"Che cosa vorresti che chi gioca provasse durante la partita?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n6","elements":[{"type":"comment","name":"n6","title":"Dopo la partita, che cosa vorresti che chi gioca pensasse o facesse di diverso nella vita di tutti i giorni?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_n7","elements":[{"type":"comment","name":"n7","title":"C''è qualcosa che non vorresti che chi gioca concludesse dal gioco?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c1","elements":[{"type":"comment","name":"c1","title":"Descrivi FODY in tre frasi, come vorresti che la raccontasse chi ha giocato.","rows":5,"autoGrow":true,"allowResize":false}],"title":"FODY nel gioco"},{"name":"p_c2","elements":[{"type":"comment","name":"c2","title":"Quali pratiche di FODY dovrebbero essere riconoscibili nel gioco? Per ciascuna: dove la ritrovi nel gioco, se c''è?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c3","elements":[{"type":"comment","name":"c3","title":"C''è qualcosa nel gioco che rappresenta FODY o il settore tessile in modo impreciso?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_c4","elements":[{"type":"comment","name":"c4","title":"A chi vorresti far giocare FODYNEST, e in quali occasioni?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_p1_1","elements":[{"type":"radiogroup","name":"p1_1","title":"Su 10 persone che giocano, quante pensi che diranno spontaneamente questa cosa: «{n2_1}»?","choices":[{"value":0,"text":"Nessuna"},{"value":1,"text":"1 persona"},{"value":2,"text":"2 persone"},{"value":3,"text":"3 persone"},{"value":4,"text":"4 persone"},{"value":5,"text":"5 persone"},{"value":6,"text":"6 persone"},{"value":7,"text":"7 persone"},{"value":8,"text":"8 persone"},{"value":9,"text":"9 persone"},{"value":10,"text":"Tutte e 10"}],"visibleIf":"{n2_1} notempty"}],"title":"Le tue previsioni","description":"Per ciascuna delle cose che hai elencato all''inizio."},{"name":"p_p1_2","elements":[{"type":"radiogroup","name":"p1_2","title":"Su 10 persone che giocano, quante pensi che diranno spontaneamente questa cosa: «{n2_2}»?","choices":[{"value":0,"text":"Nessuna"},{"value":1,"text":"1 persona"},{"value":2,"text":"2 persone"},{"value":3,"text":"3 persone"},{"value":4,"text":"4 persone"},{"value":5,"text":"5 persone"},{"value":6,"text":"6 persone"},{"value":7,"text":"7 persone"},{"value":8,"text":"8 persone"},{"value":9,"text":"9 persone"},{"value":10,"text":"Tutte e 10"}],"visibleIf":"{n2_2} notempty"}]},{"name":"p_p1_3","elements":[{"type":"radiogroup","name":"p1_3","title":"Su 10 persone che giocano, quante pensi che diranno spontaneamente questa cosa: «{n2_3}»?","choices":[{"value":0,"text":"Nessuna"},{"value":1,"text":"1 persona"},{"value":2,"text":"2 persone"},{"value":3,"text":"3 persone"},{"value":4,"text":"4 persone"},{"value":5,"text":"5 persone"},{"value":6,"text":"6 persone"},{"value":7,"text":"7 persone"},{"value":8,"text":"8 persone"},{"value":9,"text":"9 persone"},{"value":10,"text":"Tutte e 10"}],"visibleIf":"{n2_3} notempty"}]},{"name":"p_p1_4","elements":[{"type":"radiogroup","name":"p1_4","title":"Su 10 persone che giocano, quante pensi che diranno spontaneamente questa cosa: «{n2_4}»?","choices":[{"value":0,"text":"Nessuna"},{"value":1,"text":"1 persona"},{"value":2,"text":"2 persone"},{"value":3,"text":"3 persone"},{"value":4,"text":"4 persone"},{"value":5,"text":"5 persone"},{"value":6,"text":"6 persone"},{"value":7,"text":"7 persone"},{"value":8,"text":"8 persone"},{"value":9,"text":"9 persone"},{"value":10,"text":"Tutte e 10"}],"visibleIf":"{n2_4} notempty"}]},{"name":"p_p1_5","elements":[{"type":"radiogroup","name":"p1_5","title":"Su 10 persone che giocano, quante pensi che diranno spontaneamente questa cosa: «{n2_5}»?","choices":[{"value":0,"text":"Nessuna"},{"value":1,"text":"1 persona"},{"value":2,"text":"2 persone"},{"value":3,"text":"3 persone"},{"value":4,"text":"4 persone"},{"value":5,"text":"5 persone"},{"value":6,"text":"6 persone"},{"value":7,"text":"7 persone"},{"value":8,"text":"8 persone"},{"value":9,"text":"9 persone"},{"value":10,"text":"Tutte e 10"}],"visibleIf":"{n2_5} notempty"}]},{"name":"p_p2","elements":[{"type":"comment","name":"p2","title":"Quale delle cose che hai elencato pensi che arriverà meno, e perché?","rows":5,"autoGrow":true,"allowResize":false}]},{"name":"p_p3","elements":[{"type":"comment","name":"p3","title":"Che cosa temi che venga frainteso?","rows":5,"autoGrow":true,"allowResize":false}]}]}' WHERE id = 'e2b883b0-d2a6-5ba7-8014-39d500994c11';
